theorem exists_forall_norm_prod_pow_le_of_isPowerBounded {b : σ → B}
    (hb : ∀ i, IsPowerBounded (b i)) :
    ∃ Cx : ℝ, ∀ t : σ →₀ ℕ, ‖t.prod fun i k ↦ b i ^ k‖ ≤ Cx * t.prod ((1 : σ → ℝ) · ^ ·)

